"""Generate the human documentation of the registry.

  python3 -m analytics docs            # write docs/analytics-handbook/semantic/{metric-registry,glossary}.md
  python3 -m analytics docs --check    # exit 1 when a generated file differs from the registry

Output is a pure function of the registry (sorted, no timestamps), so regenerating is diff-free.
"""
from __future__ import annotations

from pathlib import Path
from typing import Any

from ..compiler.loader import Registry

BANNER = (
    "<!-- GENERATED by `python3 -m analytics docs` from analytics/registry/. Do not edit by hand: "
    "change the registry and regenerate. -->\n"
)
TYPE_VI = {"simple": "đơn", "ratio": "tỉ số", "derived": "dẫn xuất", "snapshot": "ảnh chụp"}
UNIT_VI = {"currency": "tiền", "count": "số đếm", "percent": "%", "ratio": "tỉ lệ", "index": "chỉ số"}
AGG_VI = {"sum": "Tổng", "count": "Đếm", "count_distinct": "Đếm không trùng", "min": "Nhỏ nhất", "max": "Lớn nhất"}


def _cell(text: Any) -> str:
    return str(text).replace("|", "\\|").replace("\n", " ")


def _domain(reg: Registry, metric_id: str) -> str:
    return Path(reg.sources["metric:" + metric_id]).stem


def _filters(reg: Registry, metric: dict[str, Any]) -> str:
    model = reg.semantic.get(metric.get("model", ""), {})
    gates = model.get("gates") or {}
    parts = []
    for name in metric.get("filters", []):
        parts.append(f"`{name}`" if name in gates else f"`{name}` (phân đoạn, ràng buộc trong hồ sơ khách)")
    return ", ".join(parts) or "không"


def _formula(reg: Registry, metric: dict[str, Any]) -> str:
    kind = metric["type"]
    if kind in ("simple", "snapshot"):
        model = reg.semantic.get(metric["model"], {})
        measure = next((m for m in model.get("measures", []) if m["name"] == metric["measure"]), {})
        text = f"{AGG_VI.get(measure.get('agg'), '?')} `{model.get('model')}.{measure.get('column')}`"
        if kind == "snapshot":
            validity = model.get("validity", {})
            text += f", dòng có `{validity.get('from')}` ≤ ngày tham chiếu ≤ `{validity.get('to')}`"
        if metric.get("zero_as_missing"):
            text += "; tổng 0 coi là không có (để trống)"
        return text
    if kind == "ratio":
        scale = " × 100" if metric.get("scale") == 100 else ""
        zero = "; mẫu số 0 → 0" if metric.get("on_zero_denominator") == "zero" else "; mẫu số 0 → trống"
        return f"`{metric['numerator']}` / `{metric['denominator']}`{scale}{zero}"
    return f"`{metric['expression']}`"


def render_metric_registry(reg: Registry) -> str:
    lines = [
        BANNER,
        "# Registry chỉ tiêu",
        "",
        "Nguồn chuẩn của các chỉ tiêu đã vào registry (`analytics/registry/`). Chỉ tiêu chưa có ở đây vẫn "
        "theo [metrics.md](metrics.md). Cách đọc: [analytics/README.md](../../../analytics/README.md); "
        "chú giải Việt–Anh: [glossary.md](glossary.md).",
        "",
        "| Id | Tên | Loại | Đơn vị | Nhạy cảm chi phí | Trạng thái | Miền |",
        "|---|---|---|---|---|---|---|",
    ]
    ids = sorted(reg.metrics, key=lambda m: (_domain(reg, m), m))
    for mid in ids:
        m = reg.metrics[mid]
        lines.append(
            f"| [`{mid}`](#{mid}) | {_cell(m['label']['vi'])} | {TYPE_VI.get(m['type'], m['type'])} | "
            f"{UNIT_VI.get(m['unit'], m['unit'])} | {'có' if m['cost_sensitive'] else 'không'} | "
            f"`{m['status']}` | {_domain(reg, mid)} |"
        )
    for mid in ids:
        m = reg.metrics[mid]
        lines += ["", f"## {mid}", "", f"**{_cell(m['label']['vi'])}** · *{_cell(m['label']['en'])}* · v{m['version']}", "",
                  _cell(m["description"]), ""]
        rows = [("Công thức", _formula(reg, m))]
        if m["type"] in ("simple", "snapshot"):
            rows.append(("Bộ lọc", _filters(reg, m)))
        if m["type"] == "simple":
            rows.append(("Trục thời gian", f"`{m['time_axis']}`"))
        rows += [
            ("Cộng dồn", f"`{m['additivity']}`"),
            ("NULL", f"`{m['null_policy']}`" + (f", tập rỗng → `{m['empty_result']}`" if m.get("empty_result") else "")),
        ]
        if m.get("coverage_metric"):
            rows.append(("Độ phủ đi kèm", f"[`{m['coverage_metric']}`](#{m['coverage_metric']})"))
        if m.get("legacy_names"):
            rows.append(("Tên cũ", ", ".join(f"`{n}`" for n in m["legacy_names"])))
        if m.get("replaced_by"):
            rows.append(("Thay bằng", f"[`{m['replaced_by']}`](#{m['replaced_by']})"))
        if m.get("notes"):
            rows.append(("Ghi chú", _cell(m["notes"])))
        lines += ["| | |", "|---|---|"] + [f"| {k} | {_cell(v)} |" for k, v in rows]
    return "\n".join(lines) + "\n"


def render_glossary(reg: Registry) -> str:
    entries: dict[str, tuple[str, str]] = {}
    for mid, m in reg.metrics.items():
        entries[f"metric:{mid}"] = (m["label"]["vi"], m["label"]["en"])
    for model in reg.semantic.values():
        for dim in model.get("dimensions", []):
            if dim.get("label"):
                entries[f"dimension:{model['id']}.{dim['name']}"] = (dim["label"]["vi"], dim["label"]["en"])
    lines = [
        BANNER,
        "# Chú giải Việt–Anh",
        "",
        "Nhãn của chỉ tiêu và chiều trong registry (`analytics/registry/`). Định nghĩa: "
        "[metric-registry.md](metric-registry.md).",
        "",
        "| Tiếng Việt | English | Id |",
        "|---|---|---|",
    ]
    for key, (vi, en) in sorted(entries.items(), key=lambda kv: (kv[1][0].casefold(), kv[0])):
        kind, ident = key.split(":", 1)
        ref = f"[`{ident}`](metric-registry.md#{ident})" if kind == "metric" else f"`{ident}`"
        lines.append(f"| {_cell(vi)} | {_cell(en)} | {ref} |")
    return "\n".join(lines) + "\n"


def render_all(reg: Registry) -> dict[str, str]:
    return {"metric-registry.md": render_metric_registry(reg), "glossary.md": render_glossary(reg)}
